from pathlib import Path
import base64,zlib,re,subprocess,tempfile

p=Path('index.html')
s=p.read_text(encoding='utf-8')
START='<!-- HLGB_V9198_START -->'
END='<!-- HLGB_V9198_END -->'
if START in s and END in s:
    a=s.index(START); b=s.index(END,a)+len(END); s=s[:a]+s[b:]

s=s.replace('Sistema de Gestão v91.97 Multiusuário','Sistema de Gestão v91.98 Multiusuário')
s=s.replace('>v91.97</small>','>v91.98</small>')
addon=zlib.decompress(base64.b64decode('''''')).decode('utf-8')

m=re.search(r'<script id="hlgb-v9198-script">(.*?)</script>',addon,re.S)
if not m: raise SystemExit('Script v91.98 não encontrado no addon')
with tempfile.NamedTemporaryFile('w',suffix='.js',encoding='utf-8',delete=False) as f:
    f.write(m.group(1)); js_path=f.name
r=subprocess.run(['node','--check',js_path],capture_output=True,text=True)
if r.returncode: raise SystemExit('JavaScript v91.98 inválido: '+r.stderr)

pos=s.rfind('</body>')
if pos<0: raise SystemExit('Fechamento </body> não encontrado')
s=s[:pos]+addon+'\n'+s[pos:]

for marker in ['HLGB_V9198_START','renderFactionChecklists9198','hlgbRegisterFactionMissing9198','separationGradePanel9198','v91.98','function doLogin()','HLGB_SUPABASE_URL','</html>']:
    if marker not in s: raise SystemExit('Marcador obrigatório ausente: '+marker)
if len(s)<1_000_000: raise SystemExit('index.html ficou pequeno demais')
p.write_text(s,encoding='utf-8')
print('HLGB v91.98 aplicado:',len(s),'bytes')
